扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: #!/usr/bin/env node
L2: // cgartlab-search dispatcher — zero-dependency Node ESM (Node 18+ global fetch).
L3: // Works in harnesses whose shell can reach the network (Claude Code, Codex, opencode, terminal).
L4: // In DSH's sandboxed shell (no outbound network) use web_fetch instead — see references/backends.md.
L5: //
L6: // Usage:
L7: //   node search.mjs <backends> "<query>" [--limit N] [--topic T] [--library ID] [--news]
L8: //   backends: comma list from brave,exa,context7,tencent,zhihu,bing,qqnews,hupu,so,github,hn
L9: //
L10: // Keyed backends read env vars BRAVE_SEARCH_API_KEY EXA_API_KEY CONTEXT7_API_KEY
L11: // TENCENT_NEWS_KEY ZHIHU_API_KEY (fallback: secrets.json next to SKILL.md).
L12: // Key-less backends (bing,context7,qqnews,hupu,so,github,hn) need nothing.
L13: // Output: one line of normalized JSON on stdout. Exit 0 if any backend returned results.
L14: import { readFileSync } from 'node:fs';
L15: import { execFile } from 'node:child_process';
L16: import { homedir } from 'node:os';
L17: import { fileURLToPath } from 'node:url';
L18: import { dirname, join } from 'node:path';
L19: 
L20: const here = dirname(fileURLToPath(import.meta.url));
L21: const argv = process.argv.slice(2);
L22: const flag = (n) => { const i = argv.indexOf(n); return i >= 0 ? (argv.splice(i, 2)[1] ?? null) : null; };
L23: const limit = +(flag('--limit') ?? 5);
L24: const topic = flag('--topic');
L25: const libOverride = flag('--library');
L26: const wantNews = argv.includes('--news'); if (wantNews) argv.splice(argv.indexOf('--news'), 1);
L27: const backends = (argv[0] || '').split(',').map(s => s.trim()).filter(Boolean);
L28: const query = argv.slice(1).join(' ').trim();
L29: 
L30: const ENV_KEYS = { brave: 'BRAVE_SEARCH_API_KEY', exa: 'EXA_API_KEY', context7: 'CONTEXT7_API_KEY', tencent: 'TENCENT_NEWS_KEY', zhihu: 'ZHIHU_API_KEY' };
L31: const FILE_KEYS = { brave: 'brave_api_key', exa: 'exa_api_key', context7: 'context7_api_key', tencent: 'tencent_news_key', zhihu: 'zhihu_api_key' };
L32: const secrets = {};
L33: for (const b of Object.keys(ENV_KEYS)) { const v = process.env[ENV_KEYS[b]]; if (v) secrets[b] = v; }
L34: // secrets.json lives next to SKILL.md (skill root); a copy beside this script still works.
L35: const SECRETS_CANDIDATES = [join(here, 'secrets.json'), join(here, '..', 'secrets.json')];
L36: for (const p of SECRETS_CANDIDATES) {
L37:   try {
L38:     const f = JSON.parse(readFileSync(p, 'utf8'));
L39:     for (const b of Object.keys(FILE_KEYS)) if (!secrets[b] && f[FILE_KEYS[b]]) secrets[b] = f[FILE_KEYS[b]];
L40:     break;
L41:   } catch { /* try next candidate; env-only mode when none parse */ }
L42: }
L43: const enc = s => encodeURIComponent(s);
L44: const unent = s => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
L45:   .replace(/&#39;/g, "'").replace(/&#x27;/g, "'").replace(/&#x2F;/g, '/').replace(/&amp;/g, '&');
L46: 
L47: // --- A. key-less backends ---
L48: 
L49: async function bing() {
L50:   const r = await fetch(`https://cn.bing.com/search?q=${enc(query)}&format=rss`);
L51:   if (!r.ok) return { error: `HTTP ${r.status}` };
L52:   const xml = await r.text();
L53:   const out = [];
L54:   const re = /<item>([\s\S]*?)<\/item>/g; let m;
L55:   const field = (src, tag) => {
L56:     const mm = src.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`));
L57:     return mm ? unent(mm[1].trim()) : '';
L58:   };
L59:   while ((m = re.exec(xml)) && out.length < limit) {
L60:     const t = field(m[1], 'title'), u = field(m[1], 'link');
L61:     if (!t || !u) continue;
L62:     out.push({ backend: 'bing', type: wantNews ? 'news' : 'web', title: t, url: u,
L63:       snippet: field(m[1], 'description'), published: field(m[1], 'pubDate') || null });
L64:   }
L65:   return { results: out };
L66: }
L67: 
L68: async function qqnews() {
L69:   const r = await fetch(`https://r.inews.qq.com/gw/event/hot_ranking_list?page_size=${Math.max(limit, 10)}`);
L70:   if (!r.ok) return { error: `HTTP ${r.status}` };
L71:   const j = await r.json();
